pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        // initialize with dummy counterparties; owner is set to this test contract
        address(c).call(
            abi.encodeWithSignature(
                "initialize(address,address,address,address,address,address)",
                address(1), address(2), address(3), address(4), address(5), address(6)
            )
        );
    }

    function testFuzz_property(address a, address b) public {
        vm.assume(a != address(0) && b != address(0));
        vm.assume(a != b);
        address ownerFromA;
        address ownerFromB;
        vm.prank(a);
        ownerFromA = c.owner();
        vm.prank(b);
        ownerFromB = c.owner();
        // Rule: owner() is caller-independent — every caller sees the same stored owner.
        assertTrue(ownerFromA == ownerFromB && ownerFromA != address(0));
    }
}

