pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        // initialize from an arbitrary nonzero caller; that caller must become owner
        vm.prank(actor);
        try c.initialize(IERC20(address(0)), IERC20(address(0)), IRewardRouterV2(address(0)), IGlpManager(address(0)), address(1), address(2)) {
            // ignore revert case; rule only applies when initialization succeeds
        } catch {
            return;
        }

        // rule: the initializing caller is the owner and can renounce ownership,
        // after which owner() returns address(0) for EVERY admissible caller
        vm.prank(actor);
        bool ok;
        try c.renounceOwnership() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.owner() == address(0));
    }
}

